using System;using System.IO;using System.Collections.Generic;using System.Globalization;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using TotsuDan.MapEditor;
public static class CaveWallChecks {
 [Serializable]class Family {public FamilyModel[] models;}[Serializable]class FamilyModel {public string id,sourceSha256;public CaveWallVisualsV1.Geometry source;}
 [Serializable]class Report {public string status,error;public int checks,renderers,materials;public float maxPositionError;}
 static int checks;static void Check(bool b,string s){checks++;if(!b)throw new Exception(s);}static string Arg(string s){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,s)+1];}static float F(string s){return float.Parse(s,CultureInfo.InvariantCulture);}
 public static void Run(){string output=Arg("-cave-wall-output");var report=new Report();int exit=0;try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);string export=Path.Combine(output,"export"),json=File.ReadAllText(Path.Combine(export,"cave_wall_visuals.json"));var d=CaveWallVisualsV1.Read(json);var family=JsonUtility.FromJson<Family>(File.ReadAllText(Path.Combine(output,"family-reference.json")));var hashes=new Dictionary<string,string>();var sources=new Dictionary<string,Mesh>();foreach(var m in family.models){hashes.Add(m.id,m.sourceSha256);sources.Add(m.id,CaveWallVisualsV1.BuildMesh(m.source));}Check(sources.Count==6,"Six original wall parts");
 var root=new GameObject("Isolated wall map");var byId=new Dictionary<string,GameObject>();var rock=new Material(Shader.Find("MapSharedProps/Lit"));rock.SetTexture("_BaseMap",Texture2D.whiteTexture);rock.SetColor("_BaseColor",Color.white);rock.SetFloat("_Cutoff",0);rock.SetFloat("_Cull",2);rock.SetVector("_PineBand",new Vector4(0,2,0,0));rock.SetFloat("_PlantCombinedLimit",0);
 foreach(var line in File.ReadAllLines(Path.Combine(export,"props.csv"))){var c=line.Split(',');if(c.Length<11||!sources.ContainsKey(c[1]))continue;var go=new GameObject(c[0]);go.transform.SetParent(root.transform,false);go.transform.localPosition=new Vector3(F(c[3]),F(c[4]),F(c[5]));go.transform.localRotation=Quaternion.Euler(0,F(c[6]),0);float scale=F(c[7]);go.transform.localScale=new Vector3(scale,scale*F(c[8]),scale);go.AddComponent<MeshFilter>().sharedMesh=sources[c[1]];go.AddComponent<MeshRenderer>().sharedMaterial=rock;go.AddComponent<MeshCollider>().sharedMesh=sources[c[1]];byId.Add(c[0],go);}Check(byId.Count==8,"Six normal and two fitted placements");
 var preservedBlock=new MaterialPropertyBlock();preservedBlock.SetColor("_BaseColor",new Color(.8f,.9f,1));byId["prop_0001"].GetComponent<Renderer>().SetPropertyBlock(preservedBlock);
 CliffFitsMeshV1.Apply(File.ReadAllText(Path.Combine(export,"meta.json")),File.ReadAllText(Path.Combine(export,"cliff_fits_mesh.json")),byId,hashes,rock,root.transform);
 var colliders=root.GetComponentsInChildren<MeshCollider>(true);var meshes=new Mesh[colliders.Length];var active=new bool[colliders.Length];var triangles=new string[colliders.Length];for(int i=0;i<colliders.Length;i++){meshes[i]=colliders[i].sharedMesh;active[i]=colliders[i].enabled;triangles[i]=JsonUtility.ToJson(new Ints{values=meshes[i].triangles});}int originalRenderers=Count(root);Check(originalRenderers==8,"Original rendered count");
 var previewObjects=new List<GameObject>();var pipeline=Pipeline();var sun=new GameObject("Preview sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=1.8f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(5,-9,4));sun.gameObject.AddComponent<UniversalAdditionalLightData>();var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.position=new Vector3(12,0,12);floor.transform.localScale=Vector3.one*2.4f;var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.color=new Color(.25f,.24f,.22f);floor.GetComponent<Renderer>().sharedMaterial=fm;var person=GameObject.CreatePrimitive(PrimitiveType.Capsule);person.transform.position=new Vector3(10.4f,.9f,9.6f);person.transform.localScale=new Vector3(.35f,.9f,.35f);var camera=new GameObject("Preview camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.fieldOfView=45;camera.aspect=1.333333f;camera.farClipPlane=100;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;
 foreach(bool after in new[]{false,true}){if(after)previewObjects=CaveWallVisualsV1.Apply(json,byId,hashes,rock,root.transform);foreach(string view in new[]{"top","oblique","walk"}){camera.transform.position=view=="top"?new Vector3(12,15,12):view=="walk"?new Vector3(20,1.8f,0):new Vector3(21,8,0);camera.transform.up=view=="top"?Vector3.forward:Vector3.up;camera.transform.LookAt(new Vector3(12,.8f,12));Capture(camera,Path.Combine(output,"unity-wall-"+view+"-"+(after?"after":"before")+".png"));}}
 Check(previewObjects.Count==3,"Three visual overrides");Check(Count(root)==originalRenderers,"No extra enabled renderer");for(int i=0;i<colliders.Length;i++){Check(colliders[i].sharedMesh==meshes[i]&&colliders[i].enabled==active[i],"Collider identity/enabled unchanged");Check(JsonUtility.ToJson(new Ints{values=meshes[i].triangles})==triangles[i],"Collider topology unchanged");}
 foreach(var entry in d.instances){var model=Array.Find(d.models,m=>m.id==entry.model);var go=previewObjects.Find(o=>o.name=="CaveWallVisual_"+entry.instanceId);var mesh=go.GetComponent<MeshFilter>().sharedMesh;Check(mesh.triangles.Length/3==450,"Continuous main wall triangles");var matrix=new Matrix4x4();for(int k=0;k<16;k++)matrix[k]=entry.matrix[k];var p=mesh.vertices;for(int i=0;i<p.Length;i++){var expected=matrix.MultiplyPoint3x4(new Vector3(model.render.positions[i*3],model.render.positions[i*3+1],model.render.positions[i*3+2]));float delta=Vector3.Distance(go.transform.TransformPoint(p[i]),expected);report.maxPositionError=Mathf.Max(report.maxPositionError,delta);Check(delta<.00002f,"Browser/Unity displayed vertex");}}
 var copied=new MaterialPropertyBlock();previewObjects.Find(o=>o.name=="CaveWallVisual_prop_0001").GetComponent<Renderer>().GetPropertyBlock(copied);Check(copied.GetColor("_BaseColor")==new Color(.8f,.9f,1),"Existing material block preserved");
 foreach(var go in previewObjects){var r=go.GetComponent<Renderer>();Check(r.sharedMaterial==rock&&r.receiveShadows,"Existing material and shadow retained");}
  bool rejected=false;try{CaveWallVisualsV1.Apply(json,byId,hashes,rock,root.transform);}catch(ArgumentException){rejected=true;}Check(rejected&&Count(root)==originalRenderers,"Repeated apply rejected without extra draws");var normalEntry=Array.Find(d.instances,e=>!e.fitted);var parent=byId[normalEntry.instanceId].transform;var childVisual=previewObjects.Find(o=>o.name=="CaveWallVisual_"+normalEntry.instanceId).transform;var oldPosition=parent.position;var childPosition=childVisual.position;parent.position+=new Vector3(1,0,0);Check(Vector3.Distance(childVisual.position,childPosition+Vector3.right)<1e-5f,"Normal visual follows relocation");parent.position=oldPosition;
  report.renderers=Count(root);var mats=new HashSet<Material>();foreach(var r in root.GetComponentsInChildren<Renderer>(true))if(r.enabled)mats.Add(r.sharedMaterial);report.materials=mats.Count;Check(mats.Count==1,"One rock material for all walls");foreach(var m in ShaderUtil.GetShaderMessages(rock.shader))Check(m.severity.ToString()!="Error",m.message);report.status="Passed";
 }catch(Exception e){exit=1;report.status="Failed";report.error=e.ToString();Debug.LogException(e);}report.checks=checks;File.WriteAllText(Path.Combine(output,"unity-wall.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(exit);}
 [Serializable]class Ints {public int[] values;}static int Count(GameObject root){int n=0;foreach(var r in root.GetComponentsInChildren<Renderer>(true))if(r.enabled)n++;return n;}
 static UniversalRenderPipelineAsset Pipeline(){var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=40;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.37f,.4f);return rp;}
 static void Capture(Camera c,string file){var rt=new RenderTexture(1200,900,24);rt.Create();c.targetTexture=rt;RenderPipeline.SubmitRenderRequest(c,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1200,900,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,1200,900),0,0);image.Apply();File.WriteAllBytes(file,image.EncodeToPNG());RenderTexture.active=old;c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(image);}
}
